True def transform(grid):
    h, w = len(grid), len(grid[0])
    line_rows = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    line_cols = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    line_colors = {grid[i][0] for i in line_rows} | {grid[0][j] for j in line_cols}
    if not line_colors:
        return [row[:] for row in grid]
    line_color = max(line_colors, key=lambda c: sum(v == c for row in grid for v in row))
    out = [row[:] for row in grid]
    for i in line_rows:
        if grid[i][0] == line_color:
            for j in range(w):
                out[i][j] = 2
    for j in line_cols:
        if grid[0][j] == line_color:
            for i in range(h):
                out[i][j] = 2
    return out
